#pragma once

#include <filesystem>
#include <string>
#include <string_view>

// Two loopback secrets (zero-trust between local processes):
//   ui_token       — shell / probe / smoke  → service Agent (all RPCs except Health)
//   internal_token — arli-agent worker      → service AgentHub.Session
// Files live in state_root(), mode 0600, generated by arli-daemon on start.
namespace arli::secrets {

std::filesystem::path ui_token_path();
std::filesystem::path internal_token_path();

// Read token file; empty string if missing/unreadable.
std::string load(const std::filesystem::path& file);

// Read or generate (32 random bytes, url-safe base64, no padding) and persist with 0600.
std::string load_or_create(const std::filesystem::path& file);

// Client-side resolution: env override (ARLI_UI_TOKEN / ARLI_INTERNAL_TOKEN) else file.
std::string ui_token();
std::string internal_token();

bool constant_time_equal(std::string_view a, std::string_view b);

}  // namespace arli::secrets
